cd /workspace/tmp && python3 - <<'EOF'
import json, subprocess, sys
def full(d):
    if d==0: return {"class":1}
    return {"feature":0,"threshold":0,"le":full(d-1),"gt":full(d-1)}
def count(n):
    if "class" in n: return 1
    return 1+count(n["le"])+count(n["gt"])
def depth(n):
    if "class" in n: return 0
    return 1+max(depth(n["le"]),depth(n["gt"]))
t=full(7); print("nodes",count(t),"depth",depth(t))
cfg={"version":1,"idle_timeout":10,"packet_limit":5,"prefix_width":32,
     "rules":[],"fallback":t}
p=subprocess.run([sys.executable,"-I","/workspace/submission/main.py","compile"],
                 input=json.dumps(cfg).encode(),stdout=subprocess.PIPE)
print(p.returncode, p.stdout[:200])
EOF
